     }

     const toolsConfig = this.buildToolsConfig(config);
     if (toolsConfig) {
       promptBody.tools = toolsConfig;
     }

     if (config.agent) {
       promptBody.agent = config.agent;
     } else if (config.custom_agent) {
       promptBody.agent = 'custom';
